const store = $getWorkflowStaticData('global');
const configuredCode = $('Pairing Configuration').first().json.pairingCode;
const message = $input.first().json.message || {};
const chatId = message.chat?.id;
const text = (message.text || '').trim();

if (!chatId) {
  return [{json: {readyForAgent: false, authMessage: 'Unable to identify this Telegram account.'}}];
}

store.authorizedUsers = store.authorizedUsers || {};
const userKey = String(chatId);

// Already paired: allow normal Gmail assistant usage.
if (store.authorizedUsers[userKey] === true) {
  return [{json: {readyForAgent: true}}];
}

// One-time pairing command: /pair YOUR_CODE
if (text.toLowerCase().startsWith('/pair ')) {
  const suppliedCode = text.slice(6).trim();

  if (suppliedCode && configuredCode !== 'YOUR_ONE_TIME_PAIRING_CODE' && suppliedCode === configuredCode) {
    store.authorizedUsers[userKey] = true;
    return [{json: {readyForAgent: false, authMessage: '✅ Telegram account connected successfully. You can now use the Gmail Assistant.'}}];
  }

  return [{json: {readyForAgent: false, authMessage: '❌ Invalid or expired pairing code.'}}];
}

return [{json: {readyForAgent: false, authMessage: '🔒 This Telegram account is not connected. Use /pair <pairing-code> to connect it.'}}];
